class Solution {
public:
    int lenLongestFibSubseq(vector<int>& arr) {
        int n = arr.size();
        unordered_map<int, int> idx;
        for (int i = 0; i < n; i++) idx[arr[i]] = i;
        vector<vector<int>> dp(n, vector<int>(n, 2));
        int ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                int diff = arr[i] - arr[j];
                auto it = idx.find(diff);
                if (it != idx.end() && it->second < j) {
                    int k = it->second;
                    dp[j][i] = dp[k][j] + 1;
                    ans = max(ans, dp[j][i]);
                }
            }
        }
        return ans >= 3 ? ans : 0;
    }
};

class Solution {
    public int lenLongestFibSubseq(int[] arr) {
        int n = arr.length;
        Map<Integer, Integer> idx = new HashMap<>();
        for (int i = 0; i < n; i++) idx.put(arr[i], i);
        int[][] dp = new int[n][n];
        int ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                dp[j][i] = 2;
                int diff = arr[i] - arr[j];
                Integer k = idx.get(diff);
                if (k != null && k < j) {
                    dp[j][i] = dp[k][j] + 1;
                    ans = Math.max(ans, dp[j][i]);
                }
            }
        }
        return ans >= 3 ? ans : 0;
    }
}

var lenLongestFibSubseq = function(arr) {
    const n = arr.length;
    const idx = new Map();
    for (let i = 0; i < n; i++) idx.set(arr[i], i);
    const dp = Array.from({ length: n }, () => new Array(n).fill(2));
    let ans = 0;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            const diff = arr[i] - arr[j];
            if (idx.has(diff)) {
                const k = idx.get(diff);
                if (k < j) {
                    dp[j][i] = dp[k][j] + 1;
                    ans = Math.max(ans, dp[j][i]);
                }
            }
        }
    }
    return ans >= 3 ? ans : 0;
};
